        (124, '2026-10-16T19:03:00-05:00', 2, 3, N'Ana Lopez Castro', N'Efectivo', 6.00, 0.00);
    SET IDENTITY_INSERT Pagos OFF;

    -- Stock final: unidades compradas menos unidades vendidas; no se agrega dos veces.
    UPDATE p
    SET Stock = COALESCE(c.Unidades, 0) - COALESCE(v.Unidades, 0)
    FROM Productos p
    LEFT JOIN (SELECT IdProducto, SUM(Cantidad) AS Unidades FROM DetalleCompras GROUP BY IdProducto) c ON c.IdProducto = p.IdProducto
    LEFT JOIN (SELECT IdProducto, SUM(Cantidad) AS Unidades FROM DetalleVentas GROUP BY IdProducto) v ON v.IdProducto = p.IdProducto;

    -- Confirmar la coherencia antes de guardar la carga completa.
    IF EXISTS (SELECT 1 FROM Ventas v LEFT JOIN
        (SELECT IdVenta, SUM(Subtotal) AS Total FROM DetalleVentas GROUP BY IdVenta) d ON d.IdVenta = v.IdVenta
        WHERE d.IdVenta IS NULL OR v.Total <> d.Total)
        THROW 52002, N'Hay una venta cuyo total no coincide con sus detalles.', 1;
    IF EXISTS (SELECT 1 FROM Compras c LEFT JOIN
        (SELECT IdCompra, SUM(Subtotal) AS Total FROM DetalleCompras GROUP BY IdCompra) d ON d.IdCompra = c.IdCompra
        WHERE d.IdCompra IS NULL OR c.Total <> d.Total)
        THROW 52003, N'Hay una compra cuyo total no coincide con sus detalles.', 1;
    IF EXISTS (SELECT 1 FROM vw_SaldosClientes WHERE Deuda < 0)
        THROW 52004, N'Hay un cliente con deuda negativa.', 1;

    COMMIT TRANSACTION;
    PRINT N'Carga de un mes completada correctamente.';
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    -- Restablecer la sesion si un error interrumpio un bloque IDENTITY_INSERT.
    SET IDENTITY_INSERT Usuarios OFF;
    SET IDENTITY_INSERT Clientes OFF;
    SET IDENTITY_INSERT Proveedores OFF;
    SET IDENTITY_INSERT Productos OFF;
    SET IDENTITY_INSERT Compras OFF;
    SET IDENTITY_INSERT DetalleCompras OFF;
    SET IDENTITY_INSERT Ventas OFF;
    SET IDENTITY_INSERT DetalleVentas OFF;
    SET IDENTITY_INSERT Pagos OFF;
    THROW;
END CATCH;

-- RESUMEN: cantidades guardadas en cada tabla.
SELECT N'Roles' AS Tabla, COUNT(*) AS Registros FROM Roles
UNION ALL
SELECT N'Usuarios' AS Tabla, COUNT(*) AS Registros FROM Usuarios
UNION ALL
SELECT N'Clientes' AS Tabla, COUNT(*) AS Registros FROM Clientes
UNION ALL
SELECT N'Proveedores' AS Tabla, COUNT(*) AS Registros FROM Proveedores
UNION ALL
SELECT N'Productos' AS Tabla, COUNT(*) AS Registros FROM Productos
UNION ALL
SELECT N'ProductosAlternativos' AS Tabla, COUNT(*) AS Registros FROM ProductosAlternativos
UNION ALL
SELECT N'Compras' AS Tabla, COUNT(*) AS Registros FROM Compras
UNION ALL
SELECT N'DetalleCompras' AS Tabla, COUNT(*) AS Registros FROM DetalleCompras
UNION ALL
SELECT N'Ventas' AS Tabla, COUNT(*) AS Registros FROM Ventas
UNION ALL
SELECT N'DetalleVentas' AS Tabla, COUNT(*) AS Registros FROM DetalleVentas
UNION ALL
SELECT N'Pagos' AS Tabla, COUNT(*) AS Registros FROM Pagos;
-- Cuentas disponibles: la columna PasswordHash no se muestra.
SELECT u.Login, u.Nombre, r.Nombre AS Rol, u.Activo FROM Usuarios u INNER JOIN Roles r ON r.IdRol = u.IdRol;
-- Consultas para visualizar los datos cargados.
SELECT * FROM vw_StockBajo;
SELECT * FROM vw_SaldosClientes ORDER BY Deuda DESC;
SELECT * FROM vw_AlternativasDisponibles;
SELECT CONVERT(date, Fecha) AS Dia, COUNT(*) AS Ventas, SUM(Total) AS TotalVendido
FROM Ventas GROUP BY CONVERT(date, Fecha) ORDER BY Dia;
SELECT FormaPago, COUNT(*) AS Cantidad, SUM(Total) AS Total FROM Ventas GROUP BY FormaPago;
